  const section = extractH2Section
    ? extractH2Section(markdown, "Transaction Ledger")
    : "";
  if (!section) return [];

  // Ledger blocks are introduced by ### TXN-...
  const blocks = section.split(/^###\s+/m).slice(1);

  // Keep last non-provisional row in file order for each transaction_id.
