const { sortByTransactionId } = require("../utils/sort");

const STATUS_ORDER = { pending: 0, approved: 1, rejected: 2, reversed: 3 };

function canPromoteStatus(current, incoming) {
  const c = STATUS_ORDER[String(current || "").toLowerCase()] ?? -1;
  const n = STATUS_ORDER[String(incoming || "").toLowerCase()] ?? -1;
  return n >= c;
}

function reconcileTransactions(parsed) {
  const byId = new Map();
  for (const row of parsed.ledger || []) {
    byId.set(row.transaction_id, {
      transaction_id: row.transaction_id,
      owner: row.owner,
      status: String(row.status || "").toLowerCase(),
      date: row.date,
      amount: Number(row.amount),
      effective_date: row.date,
      _correctionChangedStatusOrDate: false,
    });
  }

  // Meeting amendments: replace owner only when signed: true, and if effective present, effective >= ledger date.
  for (const amend of parsed.meetings || []) {
    if (!amend || !amend.transaction_id) continue;
    if (!amend.signed) continue;
    const target = byId.get(amend.transaction_id);
    if (!target) continue;
    if (amend.effective && String(amend.effective) < String(target.date)) continue;
    if (amend.owner) target.owner = amend.owner;
  }

  // Emails: only compliance@ can change status.
  // If sent present: apply only if sent >= ledger date. If no sent: apply if precedence allows.
  for (const email of parsed.emails || []) {
    const target = byId.get(email.transaction_id);
    if (!target) continue;

    const from = String(email.from_addr || "").toLowerCase();
    if (!from.includes("compliance@")) continue;

    const incomingStatus = String(email.status || "").toLowerCase();
    if (email.sent) {
      if (String(email.sent) >= String(target.date)) {
        target.status = incomingStatus;
      }
    } else {
      if (canPromoteStatus(target.status, incomingStatus)) {
        target.status = incomingStatus;
      }
    }
  }

  // Corrections: pick winner per (txn,field) by lexicographically greatest effective.
  const winnersByKey = new Map();
  for (const notice of parsed.corrections || []) {
    const key = `${notice.transaction_id}::${notice.field}`;
    const existing = winnersByKey.get(key);
    if (!existing || String(notice.effective) > String(existing.effective)) {
      winnersByKey.set(key, notice);
    }
  }
  const winners = [...winnersByKey.values()];

  // Apply winners but generate report sorted by notice_id ascending.
  winners.sort((a, b) => {
    if (a.notice_id < b.notice_id) return -1;
    if (a.notice_id > b.notice_id) return 1;
    return 0;
  });

  const report = [];
  for (const notice of winners) {
    const target = byId.get(notice.transaction_id);
    if (!target) continue;

    let fieldName = notice.field;
    let prev;
    if (fieldName === "owner") {
      prev = target.owner;
      target.owner = notice.value;
    } else if (fieldName === "status") {
      prev = target.status;
      target.status = String(notice.value || "").toLowerCase();
      target._correctionChangedStatusOrDate = true;
      target.effective_date = notice.effective;
    } else if (fieldName === "date") {
      prev = target.date;
      target.date = notice.value;
      target._correctionChangedStatusOrDate = true;
      target.effective_date = notice.effective;
    } else {
      // Unknown field: skip
      continue;
    }

    // Only change effective_date for corrections that modified status or date;
    // owner-only corrections keep existing effective_date.
    if (fieldName !== "status" && fieldName !== "date") {
      // keep
    }

    report.push({
      notice_id: notice.notice_id,
      transaction_id: notice.transaction_id,
      field: fieldName,
      previous_value: prev == null ? "" : String(prev),
      new_value: notice.value,
      effective: notice.effective,
    });
  }

  const items = sortByTransactionId(
    [...byId.values()].map((row) => ({
      transaction_id: row.transaction_id,
      owner: row.owner,
      status: String(row.status || "").toLowerCase(),
      effective_date: row.effective_date,
      amount_usd: Number(Number(row.amount).toFixed(2)),
      exception_reason: null, // computed later
      _ledger_date: row.date,
    })),
  );

