function buildExceptionReason(row, context) {
  const reasons = [];
  const amount = Number(row.amount_usd);
  const status = String(row.status || "").toLowerCase();

  if (amount > 10000) reasons.push("over_limit");

  // compliance_hold: final status rejected, qualifying compliance@ email referenced txn, and that email block includes sent:
  if (status === "rejected" && context.txnHasComplianceSentEmail(row.transaction_id)) {
    reasons.push("compliance_hold");
  }

  // policy_waiver: final status approved, amount_usd > 10000, and Policy Exception block exists for txn with approved_by: compliance
  if (
    status === "approved" &&
    amount > 10000 &&
    context.txnHasCompliancePolicyWaiver(row.transaction_id)
  ) {
    reasons.push("policy_waiver");
  }

  // retroactive_review: final status reversed, amount_usd > 5000, and a winning correction notice changed status for that txn.
  if (
    status === "reversed" &&
    amount > 5000 &&
    context.txnHadWinningStatusCorrection(row.transaction_id)
  ) {
    reasons.push("retroactive_review");
  }

  reasons.sort();
  return reasons.length ? reasons.join(";") : null;
}

function buildExceptions(items, parsed, report) {
  const emails = parsed.emails || [];
  const policy = parsed.policyExceptions || [];

  const complianceSentEmailTxn = new Set(
    emails
      .filter(
        (e) =>
          String(e.from_addr || "").toLowerCase().includes("compliance@") &&
          !!e.sent,
      )
      .map((e) => e.transaction_id),
  );

  const compliancePolicyTxn = new Set(
    policy
      .filter((p) => String(p.approved_by || "").toLowerCase() === "compliance")
      .map((p) => p.transaction_id),
  );

  const winningStatusCorrectionTxn = new Set(
    (report || [])
      .filter((r) => r.field === "status")
      .map((r) => r.transaction_id),
  );

  const context = {
    txnHasComplianceSentEmail: (id) => complianceSentEmailTxn.has(id),
    txnHasCompliancePolicyWaiver: (id) => compliancePolicyTxn.has(id),
    txnHadWinningStatusCorrection: (id) => winningStatusCorrectionTxn.has(id),
  };

  for (const row of items) {
    row.exception_reason = buildExceptionReason(row, context);
    delete row._ledger_date;
  }

  return items.filter((row) => row.exception_reason);
}

module.exports = { buildExceptions };
